import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

export default function AdminStudents() {
  const navigate = useNavigate();
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  useEffect(() => {
    api.get('/admin/students')
      .then(res => {
        setStudents(Array.isArray(res.data) ? res.data : []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const filtered = students.filter(s =>
    s.name?.toLowerCase().includes(search.toLowerCase()) ||
    s.email?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="app-layout">
      {/* Admin Sidebar */}
      <div className="sidebar">
        <div className="sidebar-brand">
          <span>👨‍💼 Admin Panel</span>
        </div>
        <nav className="sidebar-nav">
          <div className="nav-section-title">MANAGE</div>
          <a className="nav-item" onClick={() => navigate('/admin/dashboard')}>
            📊 Dashboard
          </a>
          <a className="nav-item" onClick={() => navigate('/admin/questions')}>
            ❓ Questions
          </a>
          <a className="nav-item active" onClick={() => navigate('/admin/students')}>
            🎓 Students
          </a>
        </nav>
      </div>

      <div className="main-content fade-in">
        <div className="page-header">
          <div>
            <h1>🎓 Students</h1>
            <p style={{ color: 'var(--mid)', fontSize: '0.9rem' }}>
              Monitor all registered students
            </p>
          </div>
        </div>

        {/* Search */}
        <input
          className="form-control"
          placeholder="🔍 Search by name or email..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ marginBottom: '1.5rem' }}
        />

        {loading ? (
          <div className="loading-wrap"><div className="spinner"></div></div>
        ) : filtered.length === 0 ? (
          <div className="empty-state">
            <div className="e-icon">📭</div>
            <h3>No students found</h3>
          </div>
        ) : (
          <div>
            <h3 style={{ marginBottom: '1rem' }}>
              👥 Total Students: {filtered.length}
            </h3>
            {filtered.map((s, i) => (
              <div className="topic-card" key={s.id}
                style={{ marginBottom: '1rem' }}>
                <div style={{ padding: '1rem' }}>
                  <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                  }}>
                    <div>
                      <p style={{ fontWeight: 600, fontSize: '1rem' }}>
                        {i + 1}. {s.name}
                      </p>
                      <p style={{ color: 'var(--mid)', fontSize: '0.85rem' }}>
                        📧 {s.email}
                      </p>
                      <p style={{ color: 'var(--mid)', fontSize: '0.85rem' }}>
                        🏢 {s.dreamCompany || 'Not set'} |
                        💼 {s.dreamRole || 'Not set'}
                      </p>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <span style={{
                        background: s.profileCompleted
                          ? '#00b89420' : '#ff444420',
                        color: s.profileCompleted
                          ? '#00b894' : '#ff4444',
                        padding: '0.3rem 0.8rem',
                        borderRadius: '20px',
                        fontSize: '0.8rem',
                        fontWeight: 600
                      }}>
                        {s.profileCompleted
                          ? '✅ Profile Complete'
                          : '⚠️ Incomplete'}
                      </span>
                      <p style={{
                        color: 'var(--mid)',
                        fontSize: '0.75rem',
                        marginTop: '0.3rem'
                      }}>
                        Joined: {s.createdAt
                          ? new Date(s.createdAt).toLocaleDateString()
                          : 'N/A'}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
